import asyncio, json
import httpx
from langgraph_sdk import get_client

def fake_server(request: httpx.Request) -> httpx.Response:
    """Hace de deployment: imprime cada request HTTP que manda el SDK."""
    body = json.loads(request.content) if request.content else None
    print(request.method, request.url.path, "| x-api-key:", request.headers.get("x-api-key"))
    if body:
        print("   body:", body)
    if request.url.path == "/threads":
        return httpx.Response(200, json={"thread_id": "t-123"})
    if request.url.path == "/assistants":
        return httpx.Response(200, json={"assistant_id": "a-456", "name": body["name"]})
    return httpx.Response(200, json={"messages": [{"type": "ai", "content": "Hola"}]})

async def main():
    client = get_client(url="https://tutor-xyz.us.langgraph.app", api_key="lsv2_FALSA")
    client.http.client._transport = httpx.MockTransport(fake_server)  # nada sale a la red

    thread = await client.threads.create()
    assistant = await client.assistants.create(
        graph_id="tutor",
        name="Tutor — Module 1",
        context={"module_id": "module-1", "store_namespace": ""},
    )
    result = await client.runs.wait(
        thread["thread_id"],
        assistant["assistant_id"],
        input={"messages": [{"role": "user", "content": "¿Qué módulo es?"}]},
    )
    print("result:", result)

asyncio.run(main())
